\end{tikzpicture}
\caption{Plot showing point $x$ being dominated by points $y_1$, $y_2$, and $y_3$. The region to the top right of $x$ is shaded pale red, and axis-parallel dashed lines go through $x$.}
\end{figure}

\end{document}
```

