Here is a simple function in Go that takes an integer as input and returns the square root of the number. This function uses the `math` package in Go to calculate the square root.

```go
package main

import (
	"fmt"
	"math"
)

func squareRoot(num float64) float64 {
	return math.Sqrt(num)
}

func main() {
	var num float64
	fmt.Print("Enter a number: ")
	fmt.Scan(&num)
	fmt.Printf("The square root of %.2f is %.2f\n", num, squareRoot(num))
}
```

